// LRU Cache: Get وPut بـO(1). السؤال يتكرر لأنه يقيس تفكيكًا لا حفظًا.
// الفكرة: Dictionary للوصول + LinkedList لترتيب الحداثة.
public sealed class LruCache<TKey, TValue> where TKey : notnull
{
    private readonly int _capacity;
    private readonly Dictionary<TKey, LinkedListNode<(TKey Key, TValue Value)>> _map;
    private readonly LinkedList<(TKey Key, TValue Value)> _order = new();

    public LruCache(int capacity)
    {
        ArgumentOutOfRangeException.ThrowIfLessThan(capacity, 1);
        _capacity = capacity;
        _map = new Dictionary<TKey, LinkedListNode<(TKey, TValue)>>(capacity);
    }

    public bool TryGet(TKey key, out TValue value)
    {
        if (_map.TryGetValue(key, out var node))
        {
            _order.Remove(node);
            _order.AddFirst(node);          // أصبح الأحدث استخدامًا
            value = node.Value.Value;
            return true;
        }
        value = default!;
        return false;
    }

    public void Put(TKey key, TValue value)
    {
        if (_map.TryGetValue(key, out var existing))
        {
            _order.Remove(existing);
            _map.Remove(key);
        }
        else if (_map.Count >= _capacity)
        {
            var oldest = _order.Last!;      // الأقل استخدامًا
            _order.RemoveLast();
            _map.Remove(oldest.Value.Key);  // الحذف من الخريطة ضروري وإلا تسرّبت
        }

        var node = _order.AddFirst((key, value));
        _map[key] = node;
    }

    public int Count => _map.Count;
}

// أسئلة المحاور المتوقعة بعده:
// 1) لماذا Remove قبل AddFirst؟ لأن العقدة قد تكون في المنتصف.
// 2) ماذا لو أضفت نفس المفتاح بقيمة جديدة؟ يجب ألا يزيد العدد.
// 3) هل هو thread-safe؟ لا — الحل: lock أو ConcurrentDictionary + قائمة محمية.
// 4) ماذا لو كانت السعة 0؟ نرمي استثناء في المُنشئ بدل سلوك غامض.
